// Package config loads credentials from the environment at startup and never
// logs secret values. See redact() for the one safe rendering we allow.
package config

import (
	"errors"
	"fmt"
	"os"
	"strings"
)

// Secrets holds the runtime credentials the service needs.
type Secrets struct {
	DatabaseURL string
	StripeKey   string
	JWTSecret   string
	RedisURL    string
}

var ErrMissing = errors.New("required secret is not set")

// Load reads every required secret from the environment. Missing values are
// reported together so the operator sees the full list at once.
func Load() (*Secrets, error) {
	s := &Secrets{
		DatabaseURL: os.Getenv("DATABASE_URL"),
		StripeKey:   os.Getenv("STRIPE_KEY"),
		JWTSecret:   os.Getenv("JWT_SECRET"),
		RedisURL:    os.Getenv("REDIS_URL"),
	}
	var missing []string
	for name, v := range map[string]string{
		"DATABASE_URL": s.DatabaseURL,
		"STRIPE_KEY":   s.StripeKey,
		"JWT_SECRET":   s.JWTSecret,
	} {
		if strings.TrimSpace(v) == "" {
			missing = append(missing, name)
		}
	}
	if len(missing) > 0 {
		return nil, fmt.Errorf("%w: %s", ErrMissing, strings.Join(missing, ", "))
	}
	return s, nil
}

// redact returns a value that is safe to write to logs.
func redact(v string) string {
	if len(v) <= 4 {
		return "****"
	}
	return v[:2] + strings.Repeat("*", len(v)-4) + v[len(v)-2:]
}

// String implements fmt.Stringer without leaking secret material.
func (s *Secrets) String() string {
	return fmt.Sprintf("Secrets{db=%s stripe=%s jwt=%s}",
		redact(s.DatabaseURL), redact(s.StripeKey), redact(s.JWTSecret))
}
